(1246590, 157934, 10261, '<td valign="top">So far this image is as close as I''ve seen to a Wall Drug (South Dakota) reference. I must say, I''m a bit surprised. Perhaps I''m the only one here who''s experienced that particular boring drive.</td>', 'So far this image is as close as I''ve seen to a Wall Drug (South Dakota) reference. I must say, I''m a bit surprised. Perhaps I''m the only one here who''s experienced that particular boring drive.', '2005-03-23 19:35:17.000000', NULL, 1),
(1246592, 157227, 10261, '<td valign="top">I''m going to go with Aesop on this one and put my money on the tortoise. I like the DOF on this shot.</td>', 'I''m going to go with Aesop on this one and put my money on the tortoise. I like the DOF on this shot.', '2005-03-23 19:37:38.000000', NULL, 1),
