INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1248238, 158488, 31211, '<td valign="top">The b&amp;w works very well, although I would have prefered to see the background blurred, because it can get a little distracting (many elements and strong light). Otherwise, nice shot.</td>', 'The b&w works very well, although I would have prefered to see the background blurred, because it can get a little distracting (many elements and strong light). Otherwise, nice shot.', '2005-03-24 17:53:58.000000', NULL, 1),
