(1250732, 157282, 2022, '<td valign="top">I am sorry, but the picture is out of focus, also grainy...but a good try (4)</td>', 'I am sorry, but the picture is out of focus, also grainy...but a good try (4)', '2005-03-26 12:59:53.000000', NULL, 1),
(1250738, 158437, 2022, '<td valign="top">Wow, I like this picture, I think it captures the idea of being bored pretty well, nice and tight compostion, I also like the duo-tone rendition. All the best (10)</td>', 'Wow, I like this picture, I think it captures the idea of being bored pretty well, nice and tight compostion, I also like the duo-tone rendition. All the best (10)', '2005-03-26 13:01:39.000000', NULL, 1),
