(1255595, 157392, 17203, '<td valign="top">Great shot- one of the few entries that clearly demonstrates boredom, yet still offers a context and skillful lighting. I think you have a good shot at ribboning with this one. Good luck! 9</td>', 'Great shot- one of the few entries that clearly demonstrates boredom, yet still offers a context and skillful lighting. I think you have a good shot at ribboning with this one. Good luck! 9', '2005-03-29 00:27:07.000000', NULL, 1),
(1255604, 158058, 17203, '<td valign="top">David! Thank you for breaking the monotony of sleeping pets and dull portraits with this colorful piece of whimsy. You could use a tan, but your lighting, composition, and concept stand well above the crowd. One of my top 5.</td>', 'David! Thank you for breaking the monotony of sleeping pets and dull portraits with this colorful piece of whimsy. You could use a tan, but your lighting, composition, and concept stand well above the crowd. One of my top 5.', '2005-03-29 00:32:25.000000', NULL, 1),
(1255611, 158608, 17203, '<td valign="top">Good idea! Your model''s expression looks a little more serious than bored, but the context is great. I think just about everybody can identify with the situation. I''d expect this plane to land near the top, if not ribbon. 9</td>', 'Good idea! Your model''s expression looks a little more serious than bored, but the context is great. I think just about everybody can identify with the situation. I''d expect this plane to land near the top, if not ribbon. 9', '2005-03-29 00:36:27.000000', NULL, 1),
(1255619, 158867, 17203, '<td valign="top">I''m not so sure I''d consider this boredom, but the lighting, color and point of view are fantastic. I''ll bet you get some low scores and still hit the top 5, maybe even a ribbon. Good luck! 8</td>', 'I''m not so sure I''d consider this boredom, but the lighting, color and point of view are fantastic. I''ll bet you get some low scores and still hit the top 5, maybe even a ribbon. Good luck! 8', '2005-03-29 00:39:47.000000', NULL, 1),
