(1256447, 158548, 35235, '<td valign="top">Now thats boaring</td>', 'Now thats boaring', '2005-03-29 13:47:26.000000', NULL, 1),
(1256452, 158937, 35235, '<td valign="top">Nothing origional about this photo except the name stiff.  Anyone could have taken it even a child.  The photographer didn''t even use a polorizer for the sky.  Given the subject matter the only way i could imagin this winning anything is if it was taken from the sky and the words boaring spelt out in the grass</td>', 'Nothing origional about this photo except the name stiff.  Anyone could have taken it even a child.  The photographer didn''t even use a polorizer for the sky.  Given the subject matter the only way i could imagin this winning anything is if it was taken from the sky and the words boaring spelt out in the grass', '2005-03-29 13:51:32.000000', NULL, 1),
(1256453, 157934, 35235, '<td valign="top">NExt time get out of the car and lye down on the snow for a better angle .. if your not willing to get your feet cold and your cloths wet your not a real photographer.</td>', 'NExt time get out of the car and lye down on the snow for a better angle .. if your not willing to get your feet cold and your cloths wet your not a real photographer.', '2005-03-29 13:52:49.000000', NULL, 1),
