(1256457, 158712, 35235, '<td valign="top">Next time park on the side of the road .. bring a tripod into the center between the cars .. throw a model behind it hunched over like they are taking a picture and step back and take the shot.. hurry .. and dont forget to set your exposure before you get in position and bring a polorizer too for the sky</td>', 'Next time park on the side of the road .. bring a tripod into the center between the cars .. throw a model behind it hunched over like they are taking a picture and step back and take the shot.. hurry .. and dont forget to set your exposure before you get in position and bring a polorizer too for the sky', '2005-03-29 13:55:08.000000', NULL, 1),
(1256468, 158999, 6668, '<td valign="top">you''ll probably get slammed on here for the filter effects, but I kind of like it, makes the sky look very intense like your driving off into the abyss.</td>', 'you''ll probably get slammed on here for the filter effects, but I kind of like it, makes the sky look very intense like your driving off into the abyss.', '2005-03-29 14:07:19.000000', NULL, 1),
(1256473, 157936, 35235, '<td valign="top">eyes are too fixed to depict iceolation destitude and board . .this image is more of a thinker pose.. slant the eyes downwards inward more and it will be board</td>', 'eyes are too fixed to depict iceolation destitude and board . .this image is more of a thinker pose.. slant the eyes downwards inward more and it will be board', '2005-03-29 14:10:32.000000', NULL, 1),
