(1256978, 157028, 33947, '<td valign="top">Very interesing picture. Like the composition. Unfortunately, resting birds do not equate with boredom to me. Could have given more points if met challenge better.</td>', 'Very interesing picture. Like the composition. Unfortunately, resting birds do not equate with boredom to me. Could have given more points if met challenge better.', '2005-03-29 19:16:38.000000', NULL, 1),
(1256981, 157347, 33250, '<td valign="top">A beautiful picture! and a beautiful little girl, but I don''t thank it quite grasps the challenge theme.</td>', 'A beautiful picture! and a beautiful little girl, but I don''t thank it quite grasps the challenge theme.', '2005-03-29 19:17:32.000000', NULL, 1),
(1256985, 156819, 12578, '<td valign="top">I love the depiction of wilson, I don''t think you could have got that bit any better its just the sharp edge on the left of the beige to blue that is shouting out fake scene, if it wernt for that it would be a much stronger image but great job on the shot anyhow :0) 7</td>', 'I love the depiction of wilson, I don''t think you could have got that bit any better its just the sharp edge on the left of the beige to blue that is shouting out fake scene, if it wernt for that it would be a much stronger image but great job on the shot anyhow :0) 7', '2005-03-29 19:21:03.000000', NULL, 1),
(1256986, 158535, 33250, '<td valign="top">I don''t find the first day of spring boring, but I really like this picture though :)</td>', 'I don''t find the first day of spring boring, but I really like this picture though :)', '2005-03-29 19:21:30.000000', NULL, 1),
(1256989, 158880, 35149, '<td valign="top">this picture is classic..great job! I love it Yhe one bottle in the front is a tad bit distracting but I think it is great gave you a 10!!</td>', 'this picture is classic..great job! I love it Yhe one bottle in the front is a tad bit distracting but I think it is great gave you a 10!!', '2005-03-29 19:24:42.000000', NULL, 1),
(1256990, 158814, 12578, '<td valign="top">Its a little too centred for my liking but im struggling to see how you could crop this better, I love the lion on the left hand side as it does look bored to tears just lying there. Great image</td>', 'Its a little too centred for my liking but im struggling to see how you could crop this better, I love the lion on the left hand side as it does look bored to tears just lying there. Great image', '2005-03-29 19:25:44.000000', NULL, 1),
