(1261619, 158927, 25028, '<td valign="top">nice :)</td>', 'nice :)', '2005-03-31 12:01:32.000000', NULL, 0),
(1261939, 156857, 27586, '<td valign="top">I was quite simply bored with the familiarity of my daily surroundings so I have taken to photographing obscure things and from unusual angles.</td>', 'I was quite simply bored with the familiarity of my daily surroundings so I have taken to photographing obscure things and from unusual angles.', '2005-03-31 14:00:39.000000', NULL, 0),
